The calibration sample holds 358 questionnaires. The rules of this chapter, written as functions of the data:

# Item pruning (Chapter 15): which items leave the pool before the network
# analyses, and how strongly each item moves while the experimental group
# trains. Needs `item_names` (the 102 items, Chapter 2).

# the 22 negatively worded items, reverse-keyed in Chapter 2
negative_items &lt;- c("NoAlienation1", "NoAlienation2",
                    "NoIsolation1", "NoIsolation2",
                    "Flourishing5", "Flourishing6", paste0("Rogerian", 7:9),
                    "ToleranceDiversity1",
                    str_subset(item_names, "NonFrustrated"))

# items with a T0 mean above the cutoff: hardly any room left to vary
items_at_ceiling &lt;- \(data, cutoff = 9.7) {
  data |&gt;
    filter(Occasion == "T0") |&gt;
    summarise(across(all_of(item_names), \(x) mean(x, na.rm = TRUE))) |&gt;
    pivot_longer(everything(), names_to = "item", values_to = "mean") |&gt;
    filter(mean &gt; cutoff) |&gt;
    pull(item)
}

# why an item leaves the pool (NA: it stays); the first reason that applies
pruning_reasons &lt;- \(data) {
  at_ceiling &lt;- items_at_ceiling(data)
  tibble(item = item_names) |&gt;
    mutate(reason = case_when(
      item %in% at_ceiling              ~ "ceiling",
      item %in% negative_items          ~ "negative wording",
      str_starts(item, "womenAttitude") ~ "women's attitude block",
      .default = NA
    ))
}

# the items that stay, in the order of the questionnaire
structure_pool &lt;- \(data) {
  pruning_reasons(data) |&gt;
    filter(is.na(reason)) |&gt;
    pull(item)
}

# change from T0 to T1 in each group, over the SD of both groups at T0;
# d_did is the difference of the two. Cell means use every questionnaire
# of a group and wave, not only persons who answered at both waves.
item_did &lt;- \(data) {
  data |&gt;
    filter(Occasion %in% c("T0", "T1")) |&gt;
    pivot_longer(all_of(item_names), names_to = "item") |&gt;
    summarise(m = mean(value, na.rm = TRUE),
              v = var(value, na.rm = TRUE),
              n = sum(!is.na(value)),
              .by = c(item, condition, Occasion)) |&gt;
    pivot_wider(names_from = c(condition, Occasion),
                values_from = c(m, v, n)) |&gt;
    mutate(sd_T0 = sqrt(((n_Experimental_T0 - 1) * v_Experimental_T0 +
                           (n_Control_T0 - 1) * v_Control_T0) /
                          (n_Experimental_T0 + n_Control_T0 - 2)),
           d_E   = (m_Experimental_T1 - m_Experimental_T0) / sd_T0,
           d_C   = (m_Control_T1 - m_Control_T0) / sd_T0,
           d_did = d_E - d_C) |&gt;
    select(item, sd_T0, d_E, d_C, d_did)
}

17.1 Two rules
When does an item go? Each community of stable items from the bootstrap of the hierarchical solution (Chapter 16.4) gets a unidimensional graded response model (GRM; Samejima, 1969), which estimates for each item its discrimination a: how sharply the item’s answers change with the person’s standing on the community. An item with a below .50 goes. A GRM needs at least three items; items of smaller communities have no a.
Unique variable analysis (UVA; Christensen et al., 2023) looks for redundancy in the network of all stable items. Two items are redundant when their weighted topological overlap reaches .25: they are linked to the same other items with similar strength, so one of them says nothing new. Of each redundant set, the item with the highest discrimination stays; ties go to the item with the higher bootstrap stability, then to the first in the alphabet.

# Redundancy and item response theory (Chapters 17 and 18). A graded
# response model (GRM) per community gives each item its discrimination a;
# unique variable analysis (UVA) finds pairs of items so close in the
# network that one of them says nothing new.

# a unidimensional GRM on the persons who answered every item
grm_fit &lt;- \(items) {
  mirt(drop_na(items), 1, itemtype = "graded", verbose = FALSE)
}

discrimination &lt;- \(fit) {
  a &lt;- coef(fit, IRTpars = TRUE, simplify = TRUE)$items[, "a"]
  tibble(item = names(a), a = unname(a))
}

# the discrimination of every item, from one GRM per community; a GRM
# needs at least three items, so items of smaller communities get NA
community_discrimination &lt;- \(items, communities) {
  grm &lt;- communities |&gt;
    filter(n() &gt;= 3, .by = community) |&gt;
    summarise(fit = list(grm_fit(items[item])), .by = community) |&gt;
    mutate(reliability = map_dbl(fit, marginal_rxx),
           a           = map(fit, discrimination)) |&gt;
    select(community, reliability, a) |&gt;
    unnest(a)
  communities |&gt;
    left_join(grm, by = c("community", "item"))
}

# sets of redundant items: a weighted topological overlap of .25 or more
redundant_sets &lt;- \(items) {
  uva &lt;- UVA(items, uva.method = "MBR", cut.off = .25, reduce = FALSE,
             verbose = FALSE)
  imap(uva$redundant, \(partners, item) sort(unique(c(item, partners))))
}

# from a redundant set keep the item with the highest discrimination, then
# the highest bootstrap stability, then the first in the alphabet
keep_one &lt;- \(set, items) {
  items |&gt;
    filter(item %in% set) |&gt;
    arrange(desc(a), desc(stability), item) |&gt;
    slice(1) |&gt;
    pull(item)
}

# the items that stay: drop the poorly discriminating (a &lt; .50) and all but
# one item of each redundant set; items has item, a and stability
prune_items &lt;- \(items, sets) {
  redundant &lt;- map(sets, \(set) setdiff(set, keep_one(set, items))) |&gt;
    list_c()
  items |&gt;
    mutate(poor = !is.na(a) & a &lt; .50,
           redundant = item %in% redundant,
           keep = !poor & !redundant)
}

# the thresholds of each item of a GRM: b1, b2, ..., the trait levels at
# which an answer above a category becomes more likely than one at or below
thresholds &lt;- \(fit) {
  coef(fit, IRTpars = TRUE, simplify = TRUE)$items |&gt;
    as_tibble(rownames = "item") |&gt;
    select(item, starts_with("b")) |&gt;
    pivot_longer(-item, names_to = "threshold", values_to = "b",
                 values_drop_na = TRUE)
}

# the information of all items of a GRM together, over the trait levels
test_information &lt;- \(fit, theta = seq(-4, 4, by = .1)) {
  tibble(theta = theta, information = testinfo(fit, matrix(theta)))
}
